class Solution {
    public int numPermsDISequence(String s) {
        int n = s.length();
        final int MOD = 1_000_000_007;
        // prev[j] = dp for length i (i positions 0..i) where last element is j-th smallest among i+1 numbers
        long[] prev = new long[1];
        prev[0] = 1;
        for (int i = 1; i <= n; ++i) {
            long[] curr = new long[i + 1];
            long[] pref = new long[i]; // prefix sums of prev[0..i-1]
            pref[0] = prev[0] % MOD;
            for (int k = 1; k < i; ++k) {
                pref[k] = (pref[k - 1] + prev[k]) % MOD;
            }
            char c = s.charAt(i - 1);
            if (c == 'I') {
                // curr[j] = sum_{k=0..j-1} prev[k]
                curr[0] = 0;
                for (int j = 1; j <= i; ++j) {
                    curr[j] = pref[j - 1];
                }
            } else { // 'D'
                // curr[j] = sum_{k=j..i-1} prev[k] = pref[i-1] - pref[j-1] (with care)
                long total = pref[i - 1];
                for (int j = 0; j <= i; ++j) {
                    long left = (j - 1 >= 0) ? pref[j - 1] : 0;
                    long val = (total - left) % MOD;
                    if (val < 0) val += MOD;
                    curr[j] = val;
                }
            }
            prev = curr;
        }
        long ans = 0;
        for (long v : prev) {
            ans = (ans + v) % MOD;
        }
        return (int) ans;
    }
}

